class User{final String id,name,email,role,profilePic,bio;const User({required this.id,required this.name,required this.email,required this.role,this.profilePic='',this.bio=''});factory User.fromJson(Map<String,dynamic> j)=>User(id:'${j['id']??j['_id']??''}',name:'${j['name']??''}',email:'${j['email']??''}',role:'${j['role']??'student'}',profilePic:'${j['profilePic']??''}',bio:'${j['bio']??''}');}
